 if(pr===130){
   threads=JSON.parse(strip(full[pr].output)).map(t=>{const n=t.comments.nodes;const c=n[n.length-1];return {id:t.id,path:t.path,line:t.line,originalLine:t.originalLine,commentCount:n.length,latest:c};});
