 reviews.forEach(r=>text(JSON.stringify({kind:"review",pr,...r,body:(r.body||"").slice(0,5000)})));
 const issues=JSON.parse(snap.prs[pr].issue_comments.output).filter(c=>c.created_at>=meta[pr].cutoff || c.updated_at>=meta[pr].cutoff);
 issues.forEach(c=>text(JSON.stringify({kind:"issue_comment",pr,...c,body:(c.body||"").slice(0,5000)})));
}

